const server=createServer(async(req,res)=>{
 try{
  const url=new URL(req.url,'http://127.0.0.1');
  if(url.pathname.startsWith('/api/')){
   const chunks=[];for await(const chunk of req)chunks.push(chunk);
   const request=new Request(`http://127.0.0.1:${server.address().port}${req.url}`,{method:req.method,headers:req.headers,...(!['GET','HEAD'].includes(req.method)?{body:Buffer.concat(chunks)}:{})});
   // Local-only identity fixture for audited caption edits. Real sessions/CSRF,
   // owner/admin/moderator and disabled checks are covered by HTTP integration tests.
   const captionFixture=/^\/api\/admin\/instagram\/batches\/[a-zA-Z0-9-]+\/caption$/.test(url.pathname)&&request.headers.get('Authorization')===`Bearer ${localToken}`;
   let r;
   const repairFixture=url.pathname==='/api/admin/studio/send/repair-layout'&&request.headers.get('Authorization')===`Bearer ${localToken}`;
   try{r=captionFixture?await instagramHandler(request,env,{adminId:1,role:'owner',provider:'dev'},url.pathname):repairFixture?await currentSendHandler(request,env,{adminId:1,role:'owner',provider:'dev'},url.pathname):await handleApiRequest(request,env);}
   catch(error){r=errorResponse(error);}
   res.writeHead(r.status,Object.fromEntries(r.headers));res.end(Buffer.from(await r.arrayBuffer()));return;
  }
  if(url.pathname==='/config.js'){res.setHeader('Content-Type','text/javascript');res.end('window.APP_CONFIG={API_BASE_URL:"",ADMIN_AUTH_MODE:"dev"};'+(serve?`sessionStorage.setItem('anonymous-submissions.dev-admin-token',${JSON.stringify(localToken)});`:''));return;}
  const path=resolve(frontend,'.'+decodeURIComponent(url.pathname)+(url.pathname.endsWith('/')?'index.html':''));
  if(!path.startsWith(frontend+sep)){res.writeHead(404);res.end();return;}
  const type={'.html':'text/html; charset=utf-8','.js':'text/javascript','.css':'text/css','.json':'application/json','.png':'image/png','.woff2':'font/woff2','.ttf':'font/ttf'}[extname(path)];
  res.setHeader('Content-Type',type??'application/octet-stream');res.end(await readFile(path));
 }catch{res.writeHead(500);res.end('Local fixture error');}
});
